def chain_follow(chain_start, chain_end):
    chain = list(chain_start)
    chain.append(chain_end)
    visited = set()
    stack = [chain_start]
    while stack:
        current = stack.pop()
        if current == chain_end:
            break
        if current not in visited:
            visited.add(current)
            for next_item in chain:
                if next_item not in visited:
                    stack.append(next_item)
    return ','.join(chain)
